export type CodiconName = keyof typeof ICONS;

export function Codicon({
  name,
  size = 24,
}: {
  name: CodiconName;
  size?: number;
}) {
  const icon = ICONS[name];
  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${icon.box} ${icon.box}`}
      fill="currentColor"
      aria-hidden="true"
    >
      {icon.paths.map((p, i) => (
        <path
          key={i}
          d={p.d}
          fillRule={"evenOdd" in p ? "evenodd" : undefined}
          clipRule={"evenOdd" in p ? "evenodd" : undefined}
        />
      ))}
    </svg>
  );
}
